    /// <summary>
    /// ReqItemTable_OnWritten
    /// </summary>
    /// <param name="sender">Form Data Source</param>
    /// <param name="e">Form data source event</param>
    [FormDataSourceEventHandler(formDataSourceStr(ReqItemTable, ReqItemTable), FormDataSourceEventType::Written),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void ReqItemTable_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun         fr                  = sender.formRun();
        ReqItemTable    metReqItemTable        = sender.cursor();
        METReqItemTable metReqItemTableExt     = fr.dataHelper().FindDataSource(formDataSourceStr(ReqItemTable, METReqItemTable)).cursor();

        if (metReqItemTable)
        {          
            metReqItemTable.metPackMETReqItemTable(metReqItemTableExt);
            metReqItemTableExt.SysExtensionSerializerExtensionMap::insertAfterBaseTable(metReqItemTable);
        }
    }
